body.script:
/* =========================
   NOVA DATA
========================= */

let posts = JSON.parse(
  localStorage.getItem("nova_posts") || "[]"
);

let products = JSON.parse(
  localStorage.getItem("nova_products") || "[]"
);

let selectedMedia = null;
let selectedMediaType = null;
let selectedCategory = "all";


/* =========================
   HELPERS
========================= */

function saveData(){

  localStorage.setItem(
    "nova_posts",
    JSON.stringify(posts)
  );

  localStorage.setItem(
    "nova_products",
    JSON.stringify(products)
  );

}

function escapeHTML(value){

  return String(value)
    .replaceAll("&","&")
    .replaceAll("<","<")
    .replaceAll(">",">")
    .replaceAll('"',""")
    .replaceAll("'","'");

}


/* =========================
   PAGES
========================= */

function showPage(id,button){

  document.querySelectorAll(".pageSection")
    .forEach(x=>x.classList.remove("active"));

  document.getElementById(id)
    .classList.add("active");

  document.querySelectorAll(".nav")
    .forEach(x=>x.classList.remove("active"));

  if(button) button.classList.add("active");

}


/* =========================
   FOLLOW
========================= */

function followUser(button){

  if(button.dataset.followed==="1"){

    button.textContent="Follow";
    button.dataset.followed="0";

  }else{

    button.textContent="Following ✓";
    button.dataset.followed="1";

  }

}


/* =========================
   MEDIA
========================= */

function previewMedia(input,type){

  const file=input.files[0];

  if(!file)return;

  const reader=new FileReader();

  reader.onload=e=>{

    selectedMedia=e.target.result;
    selectedMediaType=type;

    if(type==="image"){

      document.getElementById("mediaPreview").innerHTML=
      ``;

    }else{

      document.getElementById("mediaPreview").innerHTML=
      ``;

    }

  };

  reader.readAsDataURL(file);

}


/* =========================
   POSTS
========================= */

function publishPost(){

  const text=document
    .getElementById("postText")
    .value.trim();

  if(!text && !selectedMedia){

    alert("Write something or add media.");

    return;
  }

  const post={

    id:Date.now(),

    user:"Achraf Aza",

    avatar:"https://i.pravatar.cc/100?img=12",

    text:text,

    media:selectedMedia,

    mediaType:selectedMediaType,

    likes:0,

    liked:false,

    comments:[],

    createdAt:new Date().toISOString()

  };

  posts.unshift(post);

  saveData();

  document.getElementById("postText").value="";

  document.getElementById("mediaPreview").innerHTML="";

  selectedMedia=null;
  selectedMediaType=null;

  renderPosts();

}


function renderPosts(){

  const container=document.getElementById("posts");

  if(!posts.length){

    container.innerHTML=
    `

      🚀 Your first NOVA post will appear here.
    `;

    return;
  }

  container.innerHTML=posts.map(post=>{

    const comments=post.comments||[];

    const media=
      post.media
      ?
      (
        post.mediaType==="video"
        ?
        ``
        :
        ``
      )
      :
      "";

    return`













              ${escapeHTML(post.user)}




              Just now · 🌍






        ${
          post.text
          ?
          `

            ${escapeHTML(post.text)}
          `
          :
          ""
        }

        ${media}





            ❤️ ${post.likes}



            💬 ${comments.length} comments









            ${post.liked?"❤️":"🤍"} Like




            💬 Comment



            ↗️ Share







          ${comments.map(c=>
            `

              ${escapeHTML(c.user)}:
              ${escapeHTML(c.text)}
            `
          ).join("")}









            Send






    `;

  }).join("");

}


function likePost(id){

  const post=posts.find(p=>p.id===id);

  if(!post)return;

  post.liked=!post.liked;

  post.likes += post.liked ? 1 : -1;

  saveData();

  renderPosts();

}


function addComment(id){

  const input=document.getElementById("comment-"+id);

  if(!input)return;

  const text=input.value.trim();

  if(!text)return;

  const post=posts.find(p=>p.id===id);

  if(!post)return;

  post.comments.push({

    user:"Achraf Aza",

    text:text

  });

  saveData();

  renderPosts();

}


function focusComment(id){

  const input=document.getElementById("comment-"+id);

  if(input){

    input.focus();

  }

}


function sharePost(id){

  const post=posts.find(p=>p.id===id);

  if(!post)return;

  const text=post.text || "NOVA post";

  if(navigator.share){

    navigator.share({

      title:"NOVA",

      text:text

    });

  }else{

    navigator.clipboard
      ?.writeText(text);

    alert("Post link copied.");

  }

}


function addFeeling(){

  const input=document.getElementById("postText");

  input.value += " 😊";

  input.focus();

}


/* =========================
   BLABLA
========================= */

const reels=[

  {
    user:"@NOVA Morocco",
    text:"From Morocco 🇲🇦 to the world 🌍",
    img:"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?w=900&q=70"
  },

  {
    user:"@Explorer",
    text:"Discover amazing places 🚀",
    img:"https://images.unsplash.com/photo-1500534623283-312aade485b7?w=900&q=70"
  },

  {
    user:"@NOVA Travel",
    text:"Beautiful world ❤️",
    img:"https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=900&q=70"
  }

];


function openBlabla(){

  document.getElementById("blabla")
    .classList.add("active");

  renderReels();

}


function closeBlabla(){

  document.getElementById("blabla")
    .classList.remove("active");

}


function renderReels(){

  document.getElementById("reels").innerHTML=

  reels.map((r,i)=>`














          ${r.user}




          ${r.text}




          🎵 NOVA Mix · From Morocco 🇲🇦








          🤍
          0



          💬
          12



          ↗️
          Share






  `).join("");

}


function likeReel(button){

  const small=button.querySelector("small");

  let n=parseInt(small.textContent)||0;

  if(button.dataset.liked==="1"){

    button.innerHTML="🤍"+(n-1)+"";

    button.dataset.liked="0";

  }else{

    button.innerHTML="❤️"+(n+1)+"";

    button.dataset.liked="1";

  }

}


function shareReel(){

  if(navigator.share){

    navigator.share({

      title:"NOVA BLABLA",

      text:"Check this BLABLA on NOVA 🚀"

    });

  }else{

    alert("Share this BLABLA 🚀");

  }

}


/* =========================
   MARKETPLACE
========================= */

const demoProducts=[

  {
    id:1,
    name:"iPhone 13 · 128GB",
    price:4500,
    city:"Casablanca",
    category:"phones",
    image:"https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=500&q=70"
  },

  {
    id:2,
    name:"Wireless Headphones",
    price:350,
    city:"Rabat",
    category:"electronics",
    image:"https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=500&q=70"
  },

  {
    id:3,
    name:"Mountain Bike",
    price:1200,
    city:"Marrakech",
    category:"sport",
    image:"https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=500&q=70"
  },

  {
    id:4,
    name:"Sports Watch",
    price:900,
    city:"Tanger",
    category:"fashion",
    image:"https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=500&q=70"
  }

];


function getProducts(){

  return [...products,...demoProducts];

}


function renderChips(){

  const cats=[
    ["all","All"],
    ["phones","Phones"],
    ["electronics","Electronics"],
    ["sport","Sport"],
    ["fashion","Fashion"],
    ["home","Home"]
  ];

  document.getElementById("chips").innerHTML=

  cats.map(c=>`



      ${c[1]}



  `).join("");

}


function selectCategory(cat){

  selectedCategory=cat;

  renderChips();

  renderMarket();

}


function renderMarket(){

  renderChips();

  const q=document
    .getElementById("marketSearch")
    .value
    .toLowerCase()
    .trim();

  const list=getProducts().filter(p=>{

    const categoryOK=
      selectedCategory==="all"
      ||
      p.category===selectedCategory;

    const searchOK=
      !q
      ||
      p.name.toLowerCase().includes(q)
      ||
      p.city.toLowerCase().includes(q);

    return categoryOK && searchOK;

  });

  document.getElementById("marketGrid").innerHTML=

  list.length

  ?

  list.map(p=>`











          ${Number(p.price).toLocaleString()} DH




          ${escapeHTML(p.name)}




          📍 ${escapeHTML(p.city)}






  `).join("")

  :

  `

    No products found 😕
  `;

}


let sellImage=null;


function openSell(){

  document.getElementById("sellModal")
    .classList.add("show");

}


function closeSell(){

  document.getElementById("sellModal")
    .classList.remove("show");

}


function previewSell(input){

  const file=input.files[0];

  if(!file)return;

  const reader=new FileReader();

  reader.onload=e=>{

    sellImage=e.target.result;

    document.getElementById("sellPreview").innerHTML=

    ``;

  };

  reader.readAsDataURL(file);

}


function publishItem(){

  const name=document
    .getElementById("sellName")
    .value.trim();

  const price=Number(
    document.getElementById("sellPrice").value
  );

  const city=document
    .getElementById("sellCity")
    .value.trim();

  const category=document
    .getElementById("sellCategory")
    .value;

  if(!name || !price){

    alert("Enter product name and price.");

    return;

  }

  products.unshift({

    id:Date.now(),

    name:name,

    price:price,

    city:city || "Morocco",

    category:category,

    image:sellImage || "https://images.unsplash.com/photo-1542291026-7eec264c27aa?w=500&q=70"

  });

  saveData();

  closeSell();

  document.getElementById("sellName").value="";
  document.getElementById("sellPrice").value="";
  document.getElementById("sellCity").value="";
  document.getElementById("sellPreview").innerHTML="";
  sellImage=null;

  renderMarket();

  alert("Your product is now on NOVA Marketplace ✓");

}


/* =========================
   CHAT
========================= */

function openChat(){

  document.getElementById("chatModal")
    .classList.add("show");

}


function closeChat(){

  document.getElementById("chatModal")
    .classList.remove("show");

}


function sendMessage(){

  const input=document.getElementById("chatInput");

  const text=input.value.trim();

  if(!text)return;

  document.getElementById("chatMessages").innerHTML+=`



      You: ${escapeHTML(text)}


  `;

  input.value="";

}


/* =========================
   SEARCH
========================= */

function openSearch(){

  document.getElementById("searchModal")
    .classList.add("show");

}


function closeSearch(){

  document.getElementById("searchModal")
    .classList.remove("show");

}


function runSearch(){

  const q=document
    .getElementById("globalSearch")
    .value
    .trim()
    .toLowerCase();

  if(!q){

    document.getElementById("searchResults").innerHTML=
    `
Type something to search.`;

    return;

  }

  const result=[];

  posts.forEach(p=>{

    if(
      p.text &&
      p.text.toLowerCase().includes(q)
    ){

      result.push(
        `

          📝 ${escapeHTML(p.text)}
        `
      );

    }

  });

  getProducts().forEach(p=>{

    if(
      p.name.toLowerCase().includes(q) ||
      p.city.toLowerCase().includes(q)
    ){

      result.push(
        `

          🛒 ${escapeHTML(p.name)}
          · ${p.price} DH
        `
      );

    }

  });

  document.getElementById("searchResults").innerHTML=

    result.length
    ?
    result.join("")
    :
    `
No results found 😕`;

}


/* =========================
   NOTIFICATIONS
========================= */

function openNotifications(){

  document.getElementById("notificationModal")
    .classList.add("show");

}


function closeNotifications(){

  document.getElementById("notificationModal")
    .classList.remove("show");

}


/* =========================
   PROFILE
========================= */

function openProfile(){

  alert(
    "NOVA Profile\n\n" +
    "Achraf Aza\n" +
    "From Morocco 🇲🇦\n\n" +
    "Full profile system will connect to the NOVA backend."
  );

}


function openFriends(){

  alert(
    "Friends\n\n" +
    "The NOVA friends system will be connected to the backend."
  );

}


/* =========================
   START
========================= */

renderPosts();
renderMarket();
